```matlab
function primes = sieveOfEratosthenes(limit)
    if limit < 2
        primes = [];
        return;
    end

    % Initialize the array to true
    sieve = true(1, limit);
    sieve(1) = false; % 1 is not a prime number

    % Perform the sieve
    for i = 2:sqrt(limit)
        if sieve(i)
            sieve(i*i:i:limit) = false;
        end
    end

    % Return the indices of the true values, which are the primes
    primes = find(sieve);
end
```

