```javascript
const { Readable } = require('stream');

class MyReadableStream extends Readable {
  constructor(options) {
    super(options);
    this.data = ['some', 'data', 'to', 'stream', null]; // null indicates the end of the stream
  }

  _read(size) {
    let chunk;
    while (null !== (chunk = this.data.shift())) {
      if (!this.push(chunk)) {
        // When push returns false, stop reading until the next _read call
        break;
      }
    }
  }
}

const myStream = new MyReadableStream();

myStream.on('data', (chunk) => {
  console.log('Received:', chunk.toString());
});

myStream.on('end', () => {
  console.log('Stream finished.');
});
```

In this example, the `MyReadableStream` class extends `Readable` and implements the `_read` method, which Node.js calls whenever it needs more data. The `push` method sends data to the consumer, and returning `null` signals the end of the stream.

