        if (nread == -1) {
            if (errno == EINTR) {
                // Read was interrupted by a signal
                printf("Read was interrupted by a signal. Trying again...\n");
                continue;
            } else {
                perror("read");
                break;
            }
        } else if (nread == 0) {
            // End of file
            break;
        } else {
            // Handle the read data
            printf("Read %zd bytes\n", nread);
            // ... (process the data)
        }
    }

    return 0;
}
```

