```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpClient.Version;
import java.time.Duration;

public class KubernetesPodLogReader {

    private final HttpClient httpClient;
    private final String kubernetesApiUrl;
    private final String token; // Assume this is the token for authentication

    public KubernetesPodLogReader(String kubernetesApiUrl, String token) {
        this.kubernetesApiUrl = kubernetesApiUrl;
        this.token = token;
        this.httpClient = HttpClient.newBuilder()
                .version(Version.HTTP_1_1)
                .followRedirects(HttpClient.Redirect.NORMAL)
                .connectTimeout(Duration.ofSeconds(20))
                .build();
    }

    public String getPodLogs(String namespace, String podName) throws Exception {
        String url = String.format("%s/api/v1/namespaces/%s/pods/%s/log", kubernetesApiUrl, namespace, podName);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .timeout(Duration.ofMinutes(2))
                .header("Authorization", "Bearer " + token)
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            return response.body();
        } else {
            throw new RuntimeException("Failed to get pod logs: " + response.statusCode());
        }
    }
}
```

