{
    public function addToFavorites($name)
    {
        if (Auth::check()) {
            // Save to the database for logged-in users
            $user = Auth::user();
            Favorite::firstOrCreate([
                'user_id' => $user->id,
                'name' => $name,
            ]);
        } else {
            // Save to the session for guests
            $favorites = Session::get('favorites', []);
            if (!in_array($name, $favorites)) {
                $favorites[] = $name;
                Session::put('favorites', $favorites);
            }
        }
    }

    public function removeFromFavorites($name)
    {
        if (Auth::check()) {
            // Remove from the database for logged-in users
            $user = Auth::user();
            Favorite::where('user_id', $user->id)->where('name', $name)->delete();
        } else {
            // Remove from the session for guests
            $favorites = Session::get('favorites', []);
            if (($key = array_search($name, $favorites)) !== false) {
                unset($favorites[$key]);
                Session::put('favorites', array_values($favorites));
            }
        }
    }
}
