```javascript
class SpriteEditor {
    constructor(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.isDrawing = false;

        // Event listeners for mouse interaction
        this.canvas.addEventListener('mousedown', this.handleMouseDown.bind(this));
        this.canvas.addEventListener('mousemove', this.handleMouseMove.bind(this));
        this.canvas.addEventListener('mouseup', this.handleMouseUp.bind(this));
    }

    handleMouseDown(event) {
        this.isDrawing = true;
        this.draw(event.offsetX, event.offsetY);
    }

    handleMouseMove(event) {
        if (this.isDrawing) {
            this.draw(event.offsetX, event.offsetY);
        }
    }

    handleMouseUp(event) {
        this.isDrawing = false;
    }

    draw(x, y) {
        const pixelSize = 10; // Size of the sprite pixel
        const adjustedX = Math.floor(x / pixelSize) * pixelSize;
        const adjustedY = Math.floor(y / pixelSize) * pixelSize;

        this.ctx.fillStyle = 'black'; // Default color
        this.ctx.fillRect(adjustedX, adjustedY, pixelSize, pixelSize);
    }
}

// Usage
