  Why: number[][];
  bh: number[];
  by: number[];
  hPrev: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize;

    // Initialize weights and biases with random values
    this.Wxh = this.randomMatrix(hiddenSize, inputSize);
    this.Whh = this.randomMatrix(hiddenSize, hiddenSize);
    this.Why = this.randomMatrix(outputSize, hiddenSize);
    this.bh = new Array(hiddenSize).fill(0);
    this.by = new Array(outputSize).fill(0);
    this.hPrev = new Array(hiddenSize).fill(0);
  }

  randomMatrix(rows: number, cols: number): number[][] {
    let result = [];
    for (let i = 0; i < rows; i++) {
      result[i] = [];
      for (let j = 0; j < cols; j++) {
        result[i][j] = Math.random() * 2 - 1; // Random values between -1 and 1
      }
    }
    return result;
  }

  forward(input: number[]): number[] {
    // Compute the new hidden state
    let h = this.tanh(this.add(this.matmul(this.Wxh, input), this.add(this.matmul(this.Whh, this.hPrev), this.bh)));
    // Compute the output
    let y = this.add(this.matmul(this.Why, h), this.by);
    // Update the previous hidden state
    this.hPrev = h;
    return y;
  }

  tanh(x: number[]): number[] {
    return x.map(val => Math.tanh(val));
  }

  matmul(a: number[][], b: number[]): number[] {
    let result = new Array(a.length).fill(0);
    for (let i = 0; i < a.length; i++) {
      for (let j = 0; j < b.length; j++) {
        result[i] += a[i][j] * b[j];
      }
    }
    return result;
  }

  add(a: number[], b: number[]): number[] {
    return a.map((val, index) => val + b[index]);
  }
}

