  performTransaction(fromAccount, toAccount, amount) {
    if (fromAccount.balance >= amount) {
      fromAccount.balance -= amount;
      toAccount.balance += amount;
      console.log(`Transfer: $${amount} transferred from account ${fromAccount.id} to account ${toAccount.id}.`);
    } else {
      console.log("Transfer: Insufficient funds in the source account.");
    }
  }
}

